dashboard.definition:
{
  "title": "Support overview",
  "description": "When did it start, who is affected, and what is the likely cause?",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {"token": "time", "defaultValue": "-4h,now"}
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {"queryParameters": {"earliest": "$time.earliest$", "latest": "$time.latest$"}}
      }
    }
  },
  "dataSources": {
    "ds_failures": {
      "type": "ds.search",
      "name": "Failures with their likely cause",
      "options": {"query": "(`support_failures`) OR (`support_index` sourcetype=idlab:slapd ldap_op=BIND bind_dn=*) | eventstats values(bind_dn) as bind_dn by host conn op | where isnull(ldap_op) OR ldap_op!=\"BIND\" | eval bind_dn=mvindex(bind_dn, 0), bind_uid=if(match(bind_dn, \"^uid=\"), replace(bind_dn, \"^uid=([^,]+),.*$\", \"\\1\"), null()), bind_cn=if(match(bind_dn, \"^cn=\"), replace(bind_dn, \"^cn=([^,]+),.*$\", \"\\1\"), null()), user=coalesce(user, bind_uid), signature=if(signature==\"ldap_bind_49\" AND isnotnull(bind_uid), \"ldap_user_bind_49\", signature) | lookup support_causes signature OUTPUT cause runbook runbook_url | eval cause=coalesce(cause, \"unknown: \" . signature), who=case(isnotnull(user), user, isnotnull(bind_cn), \"service account (\" . bind_cn . \")\", like(signature, \"ldap_bind_%\"), null(), true(), \"not in log\") | fields _time user who app cause signature runbook runbook_url"}
    },
    "ds_totals": {
      "type": "ds.chain",
      "name": "Totals",
      "options": {"extend": "ds_failures", "query": "| stats count dc(user) as users min(_time) as first max(_time) as last"}
    },
    "ds_count": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| fields count"}},
    "ds_users": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| fields users"}},
    "ds_first": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| eval first=strftime(first, \"%Y-%m-%d %H:%M:%S\") | fields first"}},
    "ds_last": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| eval last=strftime(last, \"%Y-%m-%d %H:%M:%S\") | fields last"}},
    "ds_over_time": {
      "type": "ds.chain",
      "name": "Failures over time by cause",
      "options": {"extend": "ds_failures", "query": "| `support_chart(cause)`"}
    },
    "ds_by_cause": {
      "type": "ds.chain",
      "name": "When did it start, by cause",
      "options": {"extend": "ds_failures", "query": "| stats min(_time) as first_seen max(_time) as last_seen count dc(user) as n_users values(who) as who values(signature) as signatures values(app) as apps latest(runbook) as runbook latest(runbook_url) as runbook_url by cause | eval accounts=mvfilter(match(who, \"^service account\")), users=case(n_users==1, \"1 user\", n_users>1, n_users . \" users\"), affected=coalesce(mvjoin(mvappend(users, accounts), \", \"), if(isnotnull(mvfind(signatures, \"^ldap_bind_\")), \"service account\", null()), \"not in log\") | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | eval _runbook_url=runbook_url | table first_seen last_seen cause count affected apps runbook _runbook_url"}
    },
    "ds_who": {
      "type": "ds.chain",
      "name": "Users and apps affected",
      "options": {"extend": "ds_failures", "query": "| where isnotnull(who) AND who!=\"not in log\" | fillnull value=\"-\" app | stats min(_time) as first_seen max(_time) as last_seen count values(cause) as causes by who app | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\")"}
    },
    "ds_proxy_status": {
      "type": "ds.search",
      "name": "Proxy responses by status",
      "options": {"query": "`support_index` sourcetype=idlab:nginx:access status=* | eval response=if(tonumber(status) < 400, substr(status, 1, 1) . \"xx\", status) | `support_chart(response)`"}
    },
    "ds_proxy_causes": {
      "type": "ds.search",
      "name": "Proxy refusals by cause",
      "options": {"query": "`support_index` eventtype=idlab_proxy_error | stats count min(_time) as first_seen max(_time) as last_seen values(site) as routes latest(runbook) as runbook latest(runbook_url) as runbook_url by cause | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | eval _runbook_url=runbook_url | table first_seen last_seen cause count routes runbook _runbook_url"}
    },
    "ds_radius": {
      "type": "ds.search",
      "name": "RADIUS Access-Reject versus no reply",
      "options": {"query": "`support_index` (sourcetype=idlab:radius OR sourcetype=idlab:nas) radius_outcome=* | eval outcome=radius_outcome . \" (\" . if(sourcetype==\"idlab:nas\", \"NAS\", \"server\") . \")\" | `support_chart(outcome)`"}
    },
    "ds_ldap": {
      "type": "ds.search",
      "name": "LDAP binds refused (result 49)",
      "options": {"query": "`support_index` sourcetype=idlab:slapd (ldap_op=BIND OR ldap_tag=97) | stats min(_time) as time values(bind_dn) as bind_dn values(err) as err by host conn op | where err!=\"0\" | stats min(time) as first_seen max(time) as last_seen count by bind_dn err | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\"), meaning=case(err==\"49\" AND match(bind_dn, \"^uid=\"), \"invalid credentials: a user's own password\", err==\"49\", \"invalid credentials: service account, check the IdP's bind credential\", true(), \"see RFC 4511\")"}
    },
    "ds_idp_ldap": {
      "type": "ds.search",
      "name": "IdP LDAP errors",
      "options": {"query": "`support_index` eventtype=idlab_keycloak_ldap_error | stats count"}
    }
  },
  "visualizations": {
    "viz_count": {"type": "splunk.singlevalue", "title": "Failures", "dataSources": {"primary": "ds_count"}},
    "viz_users": {"type": "splunk.singlevalue", "title": "Users affected", "dataSources": {"primary": "ds_users"}},
    "viz_first": {"type": "splunk.singlevalue", "title": "First failure", "dataSources": {"primary": "ds_first"}},
    "viz_last": {"type": "splunk.singlevalue", "title": "Latest failure", "dataSources": {"primary": "ds_last"}},
    "viz_over_time": {
      "type": "splunk.column",
      "title": "Failures over time by likely cause",
      "dataSources": {"primary": "ds_over_time"},
      "options": {"stackMode": "stacked", "legendDisplay": "bottom"}
    },
    "viz_by_cause": {
      "type": "splunk.table",
      "title": "When did it start? (select a row for its runbook)",
      "options": {"showInternalFields": false, "count": 20},
      "description": "affected: end users where the logs name them, the service account for directory binds, otherwise not in log",
      "dataSources": {"primary": "ds_by_cause"},
      "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]
    },
    "viz_who": {
      "type": "splunk.table",
      "title": "Who is affected?",
      "description": "End users and service accounts named in the logs.",
      "dataSources": {"primary": "ds_who"}
    },
    "viz_proxy_status": {
      "type": "splunk.column",
      "title": "Reverse proxy: responses over time",
      "description": "Every request through the proxy by status: 2xx and 3xx grouped, errors by code. 502 and 504 come from the proxy when the app behind it fails it; 429 is the proxy's own rate limit.",
      "dataSources": {"primary": "ds_proxy_status"},
      "options": {
        "stackMode": "stacked",
        "legendDisplay": "bottom",
        "seriesColorsByField": {"2xx": "#9DA5AD", "3xx": "#C3CBD4", "400": "#E3A13B", "429": "#D6731E", "502": "#C2362F", "504": "#7E1E1B"}
      }
    },
    "viz_proxy_causes": {
      "type": "splunk.table",
      "title": "Reverse proxy: 5xx and 429 by likely cause (select a row for its runbook)",
      "description": "One row per reason in the proxy's error log. Wrong X-Forwarded headers (runbook 09) leave nothing there: they show as a Keycloak error in When did it start?",
      "options": {"showInternalFields": false},
      "dataSources": {"primary": "ds_proxy_causes"},
      "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]
    },
    "viz_radius": {
      "type": "splunk.column",
      "title": "RADIUS: Access-Reject versus no reply",
      "description": "Access-Reject: the server answered no (password, policy). No reply: it dropped or ignored the request (shared secret, unknown NAS), which users see as a timeout.",
      "dataSources": {"primary": "ds_radius"},
      "options": {"stackMode": "stacked", "legendDisplay": "bottom", "yAxisMajorTickInterval": 1}
    },
    "viz_ldap": {
      "type": "splunk.table",
      "title": "LDAP binds refused by the directory",
      "description": "Result 49 for a service account means the IdP's bind credential is wrong; for a user (uid=...), only that user's password.",
      "dataSources": {"primary": "ds_ldap"}
    },
    "viz_idp_ldap": {
      "type": "splunk.singlevalue",
      "title": "IdP LDAP errors",
      "dataSources": {"primary": "ds_idp_ldap"}
    }
  },
  "layout": {
    "type": "grid",
    "globalInputs": ["input_time"],
    "options": {"width": 1440, "height": 4064},
    "structure": [
      {"item": "viz_count", "type": "block", "position": {"x": 0, "y": 0, "w": 360, "h": 120}},
      {"item": "viz_users", "type": "block", "position": {"x": 360, "y": 0, "w": 360, "h": 120}},
      {"item": "viz_first", "type": "block", "position": {"x": 720, "y": 0, "w": 360, "h": 120}},
      {"item": "viz_last", "type": "block", "position": {"x": 1080, "y": 0, "w": 360, "h": 120}},
      {"item": "viz_over_time", "type": "block", "position": {"x": 0, "y": 120, "w": 1440, "h": 320}},
      {"item": "viz_by_cause", "type": "block", "position": {"x": 0, "y": 440, "w": 1440, "h": 1632}},
      {"item": "viz_who", "type": "block", "position": {"x": 0, "y": 2072, "w": 1440, "h": 488}},
      {"item": "viz_proxy_status", "type": "block", "position": {"x": 0, "y": 2560, "w": 1440, "h": 400}},
      {"item": "viz_proxy_causes", "type": "block", "position": {"x": 0, "y": 2960, "w": 1440, "h": 592}},
      {"item": "viz_radius", "type": "block", "position": {"x": 0, "y": 3552, "w": 720, "h": 512}},
      {"item": "viz_ldap", "type": "block", "position": {"x": 720, "y": 3552, "w": 720, "h": 392}},
      {"item": "viz_idp_ldap", "type": "block", "position": {"x": 720, "y": 3944, "w": 720, "h": 120}}
    ]
  }
}
